// ===== A ADAPTER : IDs des listes Brevo (Brevo > Contacts > Listes, l'ID est dans l'URL) =====

// Listes structurelles : pas liees a une annee, resynchronisees a chaque
// run (ajout si applicable maintenant, retrait sinon).
const STRUCTURE_LIST_IDS = {
  ecole: 8, // EDIT_ME
  entreprise: 9, // EDIT_ME
  autre: 10, // EDIT_ME
  bureau: 16, // EDIT_ME -- ID reel de ta liste "Bureau"
  ca: 18, // EDIT_ME -- ID reel de ta liste "CA"
};

// Listes de cotisation, une paire par annee : ajoute une entree chaque
// saison (garder les annees precedentes, ne rien supprimer). Une fois un
// contact ajoute a la liste d'une annee, il n'en est JAMAIS retire
// automatiquement -- c'est un instantane historique fige, pas un statut
// courant. Sans ca, un adherent qui ne renouvelle pas disparaitrait de la
// liste "cotisant 2026" l'annee suivante et on perdrait cet historique.
const COTISATION_LIST_IDS_BY_YEAR = {
  2026: { cotisant_annuel: 11, cotisant_saisonnier: 12 }, // EDIT_ME
  2027: { cotisant_annuel: 13, cotisant_saisonnier: 14 }, // ajouter ici l'an prochain
};

const items = $input.all();
const output = [];

for (const item of items) {
  const row = item.json;
  const categories = String(row.CATEGORIES || '')
    .split(';')
    .map((s) => s.trim())
    .filter(Boolean);
  const year = row.ANNEE_COTISATION || String(new Date().getFullYear());
  const yearLists = COTISATION_LIST_IDS_BY_YEAR[year] || {};

  const listIds = [];
  const unlinkListIds = [];
  const avertissements = [];

  for (const [cat, id] of Object.entries(STRUCTURE_LIST_IDS)) {
    if (categories.includes(cat)) listIds.push(id);
    else unlinkListIds.push(id);
  }

  for (const cat of ['cotisant_annuel', 'cotisant_saisonnier']) {
    if (!categories.includes(cat)) continue;
    if (yearLists[cat]) {
      listIds.push(yearLists[cat]);
    } else {
      avertissements.push(`Pas de liste Brevo configuree pour ${cat} ${year} (COTISATION_LIST_IDS_BY_YEAR)`);
    }
  }

  const attributes = {
    NOM: row.NOM || '',
    PRENOM: row.PRENOM || '',
    ADRESSE: row.ADRESSE || '',
    CODE_POSTAL: row.CODE_POSTAL || '',
    VILLE: row.VILLE || '',
    PAYS: row.PAYS || '',
    SMS: row.TELEPHONE || '',
    COTISATION_A_JOUR: row.COTISATION_A_JOUR === 'oui',
    ANNEE_COTISATION: row.ANNEE_COTISATION || '',
    TYPE_LICENCE: row.TYPE_LICENCE || '',
    NB_PERSONNES_LIEES: Number(row.NB_PERSONNES_LIEES) || 1,
    AUTRES_PERSONNES: row.AUTRES_PERSONNES || '',
  };

  output.push({
    json: {
      email: row.EMAIL,
      attributes,
      listIds,
      unlinkListIds,
      avertissements,
    },
  });
}

return output;

// Formes reelles observees en sortie du noeud HTTP Brevo (verifie dans le
// code source du noeud n8n) :
// - erreur reseau (ECONNRESET, TLS...) : json = { error: { message, name, stack, code } }
// - erreur de construction de requete (rare) : json = { error: 'message string' }
// - erreur API Brevo (4xx, neverError=true) : json = { code, message, metadata }  -- pas d'enveloppe 'error'
// - succes : json = la reponse Brevo (contient 'id' ou pas d'erreur)
function extractError(resp) {
  if (resp.code && resp.message) return `${resp.message} (${resp.code})`;
  if (resp.error) {
    if (typeof resp.error === 'string') return resp.error;
    const suffix = resp.error.code ? ` (${resp.error.code})` : '';
    return (resp.error.message || JSON.stringify(resp.error)) + suffix;
  }
  return null;
}

const items = $input.all();
const mapItems = $('Preparer payload Brevo').all();
const rows = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const mapped = mapItems[i] ? mapItems[i].json : {};
  const errorDetail = extractError(resp);
  if (errorDetail) {
    rows.push({ EMAIL: mapped.email || '', TYPE: 'erreur_api', DETAIL: errorDetail });
  }
  for (const w of (mapped.avertissements || [])) {
    rows.push({ EMAIL: mapped.email || '', TYPE: 'avertissement_config', DETAIL: w });
  }
}
function csvEscape(value) {
  const s = value === undefined || value === null ? '' : String(value);
  if (s.includes(';') || s.includes('"') || s.includes('\n') || s.includes('\r')) {
    return '"' + s.replace(/"/g, '""') + '"';
  }
  return s;
}
const headers = ['EMAIL', 'TYPE', 'DETAIL'];
const lines = [headers.join(';')];
for (const row of rows) lines.push(headers.map((h) => csvEscape(row[h])).join(';'));
const csv = lines.join('\r\n');
const binary = await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), 'erreurs_brevo.csv', 'text/csv');
return [{
  json: {
    fileName: 'erreurs_brevo.csv',
    total: items.length,
    erreurs: rows.filter((r) => r.TYPE === 'erreur_api').length,
    avertissements: rows.filter((r) => r.TYPE === 'avertissement_config').length,
  },
  binary: { data: binary },
}];
